#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table); library(ggplot2); library(patchwork); library(scales); library(ragg); library(svglite)})
source(file.path(getwd(), "scripts", "common.R"), local=TRUE)
step <- "13_nature_figures"
input_paths <- c(file.path(PROJ,"results/design/series_design_manifest.tsv"),file.path(PROJ,"results/integration/candidate_cross_study_summary.tsv"),file.path(PROJ,"results/effects/candidate_effects.tsv"),file.path(PROJ,"results/time_response/candidate_time_trajectories.tsv"),file.path(PROJ,"results/time_response/wt_time_consensus.tsv"),file.path(PROJ,"results/perturbation/candidate_regulator_summary.tsv"),file.path(PROJ,"results/models/processed_count_concordance.tsv"))
start_log(step,input_paths)
FIG <- file.path(PROJ,"figures","nature"); SRC <- file.path(PROJ,"results","figure_source_data"); safe_mkdir(FIG); safe_mkdir(SRC)
theme_nature <- theme_classic(base_size=7,base_family="Arial") + theme(axis.line=element_line(linewidth=.3),axis.ticks=element_line(linewidth=.3),strip.text=element_text(size=6.5,face="bold"),plot.title=element_text(size=8,face="bold",hjust=0),plot.subtitle=element_text(size=6.5,hjust=0),legend.title=element_text(size=6.5),legend.text=element_text(size=5.8),panel.grid=element_blank(),plot.margin=margin(3,4,3,4))
theme_set(theme_nature)
pal_unit <- c(TPM="#3775BA",FPKM="#7B61A8",count="#42949E")
pal_tier <- c("Tier 1: multi-GSE supported"="#0F4D92","Tier 2: focused follow-up"="#42949E","Tier 3: exploratory/low support"="#B8B8B8")
read_dt <- function(p) fread(p,sep="\t",encoding="UTF-8",fill=TRUE)
design <- read_dt(input_paths[1]); summary <- read_dt(input_paths[2]); effects <- read_dt(input_paths[3]); traj <- read_dt(input_paths[4]); time_cons <- read_dt(input_paths[5]); reg <- read_dt(input_paths[6]); concord <- read_dt(input_paths[7])
save_pub <- function(plot,stem,w=183,h=120){base<-file.path(FIG,stem); svglite::svglite(paste0(base,".svg"),width=w/25.4,height=h/25.4);print(plot);dev.off();grDevices::cairo_pdf(paste0(base,".pdf"),width=w/25.4,height=h/25.4,family="Arial");print(plot);dev.off();ragg::agg_tiff(paste0(base,".tiff"),width=w/25.4,height=h/25.4,units="in",res=600,compression="lzw");print(plot);dev.off();ragg::agg_png(paste0(base,".png"),width=w/25.4,height=h/25.4,units="in",res=300);print(plot);dev.off()}
tag <- function(p,x) p+labs(tag=x)+theme(plot.tag=element_text(face="bold",size=9),plot.tag.position=c(.01,.99))

## Fig. 1: design, sample coverage and processed/count robustness.
design[,label:=factor(matrix_id,levels=rev(matrix_id))]
design[,t0:=suppressWarnings(as.numeric(sub("h$", "", sub(";.*", "", time_points))))]
design[,t1:=suppressWarnings(as.numeric(sub("h$", "", sub(".*;", "", time_points))))]
design[grepl("Day5|unknown",time_points),`:=`(t0=0,t1=0)]
write_tsv(design[,.(matrix_id,gse,unit,n_samples,genotypes,time_points,treatments,matrix_status,mapping_confidence)],file.path(SRC,"Fig1a_design.tsv"))
p1a <- ggplot(design,aes(y=label))+geom_segment(aes(x=t0,xend=t1,yend=label),linewidth=1.1,colour="#C9C9C9")+geom_point(aes(x=t0,size=n_samples,colour=unit,shape=matrix_status),stroke=.35)+geom_point(aes(x=t1,size=n_samples,colour=unit,shape=matrix_status),stroke=.35)+scale_colour_manual(values=pal_unit)+scale_size_continuous(range=c(1.5,4.2))+scale_x_continuous(breaks=c(0,6,12,18,24,36),limits=c(-2,38),expand=c(0,0))+labs(x="Sampling time (h; Day 5 shown at 0)",y=NULL,colour="Matrix unit",size="Samples",shape="Audit status")+theme(legend.position="bottom")
write_tsv(design[,.(matrix_id,gse,unit,n_samples,genotypes,treatments)],file.path(SRC,"Fig1b_matrix_composition.tsv"))
p1b <- ggplot(design,aes(x=reorder(matrix_id,n_samples),y=n_samples,fill=unit))+geom_col(width=.72)+scale_fill_manual(values=pal_unit)+coord_flip()+labs(x=NULL,y="GEO samples per matrix",fill="Unit")+theme(legend.position="bottom")
concord[,pair:=gsub("_TPM|_FPKM","",processed_matrix)]; cs<-concord[,.(n=.N,direction_agreement=mean(direction_agree,na.rm=TRUE)),by=pair]; write_tsv(cs,file.path(SRC,"Fig1c_concordance.tsv"))
p1c <- ggplot(cs,aes(x=reorder(pair,direction_agreement),y=direction_agreement,fill=direction_agreement))+geom_col(width=.65)+geom_text(aes(label=percent(direction_agreement,accuracy=.1)),hjust=-.08,size=2.5)+scale_fill_gradient(low="#B8C8D8",high="#0F4D92")+scale_y_continuous(labels=percent,limits=c(0,1.08),expand=c(0,0))+coord_flip()+labs(x=NULL,y="Direction agreement")+theme(legend.position="none")
fig1 <- (tag(p1a,"a")|tag(p1b,"b")|tag(p1c,"c"))+plot_layout(widths=c(1.5,.9,.9))+plot_annotation(title="ATCC 24927 GPCR transcriptome resource and design audit",subtitle="19 matrices from 12 GEO accessions; models remain within series and expression unit")
save_pub(fig1,"Fig1_resource_design_audit",183,105)

## Fig. 2: all-candidate atlas and prioritization.
wt<-effects[contrast_type=="wt_induction" & unit!="count" & is.finite(log2fc),.(log2fc=median(log2fc,na.rm=TRUE)),by=.(candidate_id,gse)]; wt<-merge(wt,summary[,.(candidate_id,priority_rank,priority_tier)],by="candidate_id",all.x=TRUE); write_tsv(wt,file.path(SRC,"Fig2a_WT_induction_atlas.tsv"))
p2a<-ggplot(wt,aes(x=gse,y=reorder(candidate_id,-priority_rank),fill=log2fc))+geom_tile()+scale_fill_gradient2(low="#3775BA",mid="white",high="#B64342",midpoint=0,na.value="#EEEEEE")+labs(x="GEO accession",y="93 candidates (priority order)",fill="Median WT induction log2FC")+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),axis.text.x=element_text(angle=45,hjust=1),legend.position="bottom")
write_tsv(summary[,.(candidate_id,priority_rank,priority_tier,priority_score,detected_gse_n_conservative,wt_induction_supported_gse_n_conservative,tm_count,sequence_length)],file.path(SRC,"Fig2b_priority.tsv"))
p2b<-ggplot(summary,aes(x=detected_gse_n_conservative,y=priority_score,colour=priority_tier,size=tm_count))+geom_jitter(width=.12,height=0,alpha=.86,stroke=.25)+scale_colour_manual(values=pal_tier,drop=FALSE)+scale_size_continuous(range=c(1.2,4))+labs(x="Conservative baseline breadth (GEO count)",y="Priority score",colour="Priority tier",size="TM count")+theme(legend.position="bottom")
top20<-summary[order(priority_rank)][1:min(20,.N),.(candidate_id,priority_rank,priority_score,priority_tier)]; write_tsv(top20,file.path(SRC,"Fig2c_top20.tsv")); p2c<-ggplot(top20,aes(x=reorder(candidate_id,priority_score),y=priority_score,fill=priority_tier))+geom_col(width=.7)+coord_flip()+scale_fill_manual(values=pal_tier,drop=FALSE)+labs(x=NULL,y="Priority score",fill="Priority tier")+theme(legend.position="bottom")
fig2<-(tag(p2a,"a")/(tag(p2b,"b")|tag(p2c,"c")))+plot_layout(heights=c(1.35,1))+plot_annotation(title="Cross-GEO expression evidence across the 93 GPCR candidates",subtitle="Priority scores support experimental triage; they do not establish receptor function")
save_pub(fig2,"Fig2_cross_GEO_candidate_atlas",183,155)

## Fig. 3: temporal dynamics and perturbation dependence.
sel<-time_cons[order(-consensus_max_abs_log2fc)][1:min(12,.N),candidate_id]; tt<-traj[genotype=="WT" & candidate_id%in%sel & is.finite(induction_log2fc)]; write_tsv(tt,file.path(SRC,"Fig3a_top12_WT_trajectories.tsv")); p3a<-ggplot(tt,aes(x=time_h,y=induction_log2fc,group=matrix_id,colour=matrix_id))+geom_hline(yintercept=0,linewidth=.25,linetype=2,colour="#777777")+geom_line(linewidth=.45)+geom_point(size=.8)+facet_wrap(~candidate_id,ncol=4,scales="free_x")+scale_colour_brewer(palette="Dark2")+labs(x="Hours after induction",y="WT induction log2FC",colour="Matrix")+theme(legend.position="bottom",strip.text=element_text(size=5.3))
ii<-reg[,.(candidate_id,regulator,interaction_max_abs_log2fc,dependency_class,provisional_mapping)]; write_tsv(ii,file.path(SRC,"Fig3b_interaction_magnitude.tsv")); p3b<-ggplot(ii,aes(x=regulator,y=reorder(candidate_id,-interaction_max_abs_log2fc),fill=interaction_max_abs_log2fc))+geom_tile()+scale_fill_viridis_c(option="C",na.value="#EEEEEE")+labs(x="Perturbation axis",y="93 candidates",fill="Max |interaction log2FC|")+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),axis.text.x=element_text(angle=45,hjust=1),legend.position="bottom")
dep<-reg[,.(N=.N),by=dependency_class]; write_tsv(dep,file.path(SRC,"Fig3c_dependency_classes.tsv")); p3c<-ggplot(dep,aes(x=reorder(dependency_class,N),y=N,fill=dependency_class))+geom_col(width=.68)+coord_flip()+scale_fill_manual(values=c(interaction_supported="#0F4D92",mutant_induction_preserved="#42949E",mutant_induction_lost_or_changed="#B64342",baseline_genotype_shift="#9A4D8E",weak_or_unresolved="#B8B8B8"),guide="none")+labs(x=NULL,y="Candidate–regulator records")
fig3<-(tag(p3a,"a")/(tag(p3b,"b")|tag(p3c,"c")))+plot_layout(heights=c(1.15,1))+plot_annotation(title="Temporal GPCR responses and perturbation-dependent signatures",subtitle="Time trajectories and regulator effects are retained as separate within-series evidence")
save_pub(fig3,"Fig3_time_and_perturbation_signatures",183,160)

legends<-c("Fig. 1 | ATCC 24927 GPCR transcriptome resource and design audit. a, Sampling windows and matrix units for all 19 matrices. b, Matrix-level sample composition. c, Direction agreement between paired processed-expression and raw-count models for the same GEO design. GSE253759/GSE215079 duplicate status and provisional GSE303416 mapping are documented in source tables.","Fig. 2 | Cross-GEO expression evidence across 93 GPCR candidates. a, All-candidate WT induction heatmap using median within-accession log2FC. b, Conservative baseline breadth versus priority score; point size denotes TM count. c, Top-20 candidates. Priority is a screening metric.","Fig. 3 | Temporal GPCR responses and perturbation-dependent signatures. a, WT induction trajectories for 12 strongest consensus candidates. b, Maximum absolute genotype–time interaction by regulator axis. c, Candidate–regulator dependency classes. Three biological replicates per group are used in limma/DESeq2 models.")
writeLines(legends,file.path(PROJ,"results","figure_legends.md"),useBytes=TRUE)
contract<-c("# Nature-style figure contract","","Backend: R; target width: 183 mm; archetype: asymmetric mixed-modality quantitative composite.","Core conclusion: the ATCC 24927 GPCR resource supports condition-specific and time-resolved candidate prioritization while preserving GEO-level design and duplicate controls.","Panel hierarchy: Fig. 1 establishes the resource; Fig. 2 is the discovery atlas; Fig. 3 connects temporal dynamics to perturbation dependence.","Statistics: within-series log2FC; candidate counts and direction agreement are shown with source-data tables.","Risks: GSE253759 is excluded from independent support; GSE303416 is provisional; cross-GEO network consensus is not claimed.")
writeLines(contract,file.path(PROJ,"results","figure_contract.md"),useBytes=TRUE)
src<-list.files(SRC,full.names=TRUE); out<-list.files(FIG,full.names=TRUE); write_tsv(data.frame(file=src,sha256=vapply(src,file_sha256,character(1))),file.path(PROJ,"checksums","step13_figure_source_data_sha256.tsv")); write_tsv(data.frame(file=out,sha256=vapply(out,file_sha256,character(1))),file.path(PROJ,"checksums","step13_nature_figures_sha256.tsv"))
cat("figure_files:",length(out),"\nsource_data_files:",length(src),"\n"); finish_log()
